import java.io.BufferedReader
import java.io.InputStreamReader
import kotlin.math.sqrt

fun inpf(): List<Double> = readLine()!!.trim().split(" ").map { it.toDouble() }

fun inps(): List<String> = readLine()!!.trim().split(" ")

fun copy(a: Any): Any {
    throw UnsupportedOperationException("Deep copy via serialization is not directly supported in Kotlin.")
}

fun kaijo(n: Long, r: Long = 1_000_000_007L): Long {
    if (n < 2) return 1L
    var memo = 1L
    for (u in 2L..n) {
        memo = (memo * u) % r
    }
    return memo
}

fun na(n: Int, d: Int = 0): IntArray = IntArray(n) { d }

fun na2(n: Int, m: Int, d: Int = 0): Array<IntArray> = Array(n) { IntArray(m) { d } }

fun na3(n: Int, m: Int, l: Int, d: Int = 0): Array<Array<IntArray>> =
    Array(n) { Array(m) { IntArray(l) { d } } }

fun inp(): List<Long> = readLine()!!.trim().split(" ").map { it.toLong() }

fun r_up(a: Long, b: Long): Long = (a + b - 1) / b

fun sum(a: List<Long>): Long = a.sum()

fun primeDivision(n: Long): List<Pair<Long, Int>> {
    var x = n
    val res = mutableListOf<Pair<Long, Int>>()
    var p = 2L
    while (p * p <= x) {
        if (x % p == 0L) {
            var cnt = 0
            while (x % p == 0L) {
                x /= p
                cnt++
            }
            res.add(p to cnt)
        }
        p += if (p == 2L) 1 else 2
    }
    if (x > 1L) res.add(x to 1)
    return res
}

fun main() {
    val n = inp()[0]
    val d = primeDivision(n)
    if (d.size == 1) {
        println(d[0].first)
    } else {
        println(1)
    }
}

